		/** 
		 * Tests creating a new Evidence.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Evidence");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Evidence" );

			try {            
				Evidence entity = EvidenceService.getEvidenceInstance().createEvidence( generateNewEntity() );
				thePrimaryKey = entity.getEvidenceId();
				LOGGER.info( "-- Successfully created a Evidence with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Evidence. 
		 */
		public Evidence testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Evidence" );

			Evidence entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Evidence with primary key" );
			msg.append( thePrimaryKey );
			
			EvidenceFetchOneSummary fetchOneSummary = new EvidenceFetchOneSummary( thePrimaryKey );

			try {
				entity = EvidenceService.getEvidenceInstance().getEvidence( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Evidence " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Evidence.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Evidence." );

			StringBuilder msg = new StringBuilder( "Failed to update a Evidence : " );        
			Evidence entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Evidence." );

				// for use later on...
				thePrimaryKey = entity.getEvidenceId();

				EvidenceService proxy = EvidenceService.getEvidenceInstance();            
				proxy.updateEvidence( entity );   

				LOGGER.info( "-- Successfully saved Evidence - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Evidence.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Evidence." );

			try{
			    Evidence entity = testRead(); 
				EvidenceService.getEvidenceInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Evidence with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Evidence with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Evidences.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Evidences:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Evidence : " );        
			List<Evidence> collection  = null;

			try {
				// call the static get method on the EvidenceService
				collection = EvidenceService.getEvidenceInstance().getAllEvidence();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Evidence entity = null;            
					Iterator<Evidence> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getEvidenceId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/**
		 * Assigns a common log handler for each test class in the suite
		 * @param		handler	Handler
		 * @return		EvidenceTest
		 */
		public EvidenceTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Evidence
		 * 
		 * @return Evidence
		 */
		protected Evidence generateNewEntity() {
			Evidence entity = new Evidence( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new URL(),   new Date(),  null,  null,  null,  null,  EvidenceType.values()[0] );
			
			return( entity );
		}

